#import "MenuMetersPref+Reporting.h"
#import "MenuMeterReporterPrefsViewController.h"

@implementation MenuMetersPref (Reporting)

- (void)setupReportingTab {
    // Must run before the toolbar is built: the toolbar's items are generated by
    // walking prefTabs.tabViewItems.
    if ([prefTabs indexOfTabViewItemWithIdentifier:@"paperplane"] != NSNotFound) return;

    MenuMeterReporterPrefsViewController *controller =
        [[MenuMeterReporterPrefsViewController alloc] init];

    NSTabViewItem *item = [[NSTabViewItem alloc] initWithIdentifier:@"paperplane"];
    item.label = NSLocalizedString(@"Reporting", @"reporting tab title");
    // Setting the view controller also installs its view and keeps it alive, so
    // there is nothing else holding on to the controller.
    item.viewController = controller;

    // Appended, never inserted: openAbout: selects the About tab by its index.
    [prefTabs addTabViewItem:item];
}

@end
